    /// <summary>按厂商码（KS/PG…）反查整型；大小写不敏感。</summary>
    public static bool TryParse(string code, out int type)
    {
        type = 0;
        if (string.IsNullOrWhiteSpace(code))
            return false;
        foreach (var kv in Map)
        {
            if (string.Equals(kv.Value.Code, code.Trim(), StringComparison.OrdinalIgnoreCase))
            {
                type = kv.Key;
                return true;
            }
        }

        return false;
    }

    public static Dictionary<string, string> CategoryDict(int type)
    {
        var dict = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        if (!Map.TryGetValue(type, out var item)) return dict;
        foreach (var c in item.Categories)
        {
            if (CategoryLabel.TryGetValue(c, out var label))
                dict[c] = label;
            else
                dict[c] = c;
        }
        return dict;
    }

